head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > appearance]<br/>AutoComplete 의 오른쪽에 아이템 리스트창을 여는 버튼을 표시할지 설정합니다.",
    "validation" : [
        "display 설정 시, 아이템 리스트창을 여는 화살표 버튼을 표시합니다.",
        "미설정 시, 아이템 리스트창을 여는 화살표 버튼을 표시합니다.",
        "none 설정 시, 아이템 리스트창을 여는 화살표 버튼을 표시하지 않습니다.",
        "none 설정 시, 버튼으로 아이템 리스트창을 열 수 없으므로 키보드 입력이나 스크립트로 열어야 합니다.",
    ]
}



// 리스트창 확인 버튼을 누르는 시점의 리스트창 열림 여부, 표시된 아이템
scwin.gVar = { "listInfo" : "" };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "2" },
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Sejong", "value" : "4" }
    ]);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_appearance.setValue("display");

    // 리스트창 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 열림 여부와 아이템을 기록
    btn_getListInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[절차]\n1. 화살표 버튼 확인\n2. 화살표 버튼 클릭 -> 리스트창 확인\n3. 입력창 클릭 -> 리스트창 확인\n4. 입력창 클릭 -> 입력값을 모두 지우고 대문자 S 입력 -> 리스트창 확인\n5. Target 재생성 버튼 클릭 직후 Tab 키로 입력창에 포커스 이동 -> 아래 방향키 입력 -> 리스트창 확인\n6. openTable\n[확인]\n- 화살표 버튼 / 아래 방향키 / openTable : 전체 아이템\n- 입력창 클릭 / 글자 입력 : 입력값으로 검색된 아이템"', '', 'label1');

    let properties = {
        appearance : con_appearance.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
};



// 아이템 리스트창 열림 여부와 표시된 아이템 (닫혀 있으면 열림 여부만)
scwin.getListInfo = function () {
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    let bOpen = false;
    if (itemTableElem) {
        let objStyle = getComputedStyle(itemTableElem);
        bOpen = objStyle.display !== "none" && objStyle.visibility !== "hidden";
    }
    if (!bOpen) {
        return "리스트창 열림 : false";
    }
    // 숨겨진 Row 는 제외하고 화면에 보이는 아이템만 수집
    let arrLabel = [];
    let rowList = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
    for (let i = 0; i < rowList.length; i++) {
        if (rowList[i].offsetHeight > 0) {
            arrLabel.push(rowList[i].textContent.trim());
        }
    }
    return "리스트창 열림 : true / 아이템 : " + arrLabel.join(", ");
};



// 화살표 버튼 표시 여부 출력 (validation 1 ~ 3)
scwin.btn_getButtonInfo_onclick = function (e) {
    let buttonElem = document.querySelector("[id='" + target1.id + "_button'], [id='" + target1.id + "_div_arrow']");
    let bDisplay = !!buttonElem && buttonElem.offsetWidth > 0 && getComputedStyle(buttonElem).visibility !== "hidden";
    let strAppearance = con_appearance.getValue() === "" ? "미설정" : con_appearance.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("appearance : " + strAppearance + " -> 화살표 버튼 표시 : " + bDisplay);
};



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 열림 여부, 표시된 아이템 기록
scwin.captureListState = function (e) {
    scwin.gVar.listInfo = scwin.getListInfo();
};



// 화살표 버튼 클릭 / 입력창 클릭 / 키보드 입력 후 리스트창 열림 여부, 표시된 아이템 출력 (validation 1, 2, 4)
scwin.btn_getListInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue(scwin.gVar.listInfo);
};



// 스크립트로 아이템 리스트창 열기 (validation 4)
scwin.btn_openTable_onclick = function (e) {
    target1.openTable();
    wf_body_bottom.getObj("scwin").setReturnValue("openTable 실행 -> " + scwin.getListInfo());
};
